public static ArrayList<Complex> <mask>(int n, int log2n, ArrayList<Complex> x) {
    int reverse;
    for (int i = 0; i < n; i++) {
        reverse = put(i, log2n);
        if (i < reverse) {
            Collections.swap(x, i, reverse);
        }
    }
    return x;
}

