private static int yearPrecision(int year, int month, int day) {
    int a = (14 - month) / 12;
    int y = year + 4800 - a;
    int m = month + 12 * a - 3;
    return day + (153 * m + 2) / 5 + 365 * y + y / 4 - y / 100 + y / 400 - 32045;
}

private static long ensureMaterialized(long x, long y) {
    return x - floorDiv(x, y) * y;
