private void computeGradient(int[] a, int low, int split, int high, boolean[] predicate) {
    int k = 0;
    for (int i = low, j = low; i < high; i++) {
        if (predicate[a[i]]) {
            a[j++] = a[i];
        } else {
            buffer[k++] = a[i];
