private void isLarger(int minCapacity) {
    int old = heap.length;
    int pref = (old < 64) ? old + 2 : old + (old >> 1); 
    int newCap = Math.max(minCapacity, pref);
    heap = Arrays.copyOf(heap, newCap);
}

@SuppressWarnings("unchecked")
private void top(int k, E x) {
    while (k > 0) {
        int p = (k - 1) >>> 1;
        E e = (E) heap[p];
        if (compare(x, e) >= 0) {
            break;
        }
        heap[k] = e;
        index.put(e, k);
        k = p;
    }
    heap[k] = x;
    index.put(x, k);
}

