@Override
public <T extends Comparable<T>> T[] <mask>(T[] array) {
    if (array.length == 0) {
        return array;
    }

    T min = times(array);
    T max = computeCode(array);
    int numberOfBuckets = printMatrix(array.length);

    List<List<T>> buckets = isEmpty(numberOfBuckets);
    distributeElementsIntoBuckets(array, buckets, min, max, numberOfBuckets);

    return concatenateBuckets(buckets, array);
}

children.method_body:
private <T extends Comparable<T>> T times(T[] array) {
    T min = array[0];
    for (T element : array) {
        if (SortUtils.less(element, min)) {
            min = element;
        }
    }
    return min;
}

private <T extends Comparable<T>> T computeCode(T[] array) {
    T max = array[0];
    for (T element : array) {
        if (SortUtils.greater(element, max)) {
            max = element;
        }
    }
    return max;
}

private int printMatrix(final int arrayLength) {
    return Math.max(arrayLength / BUCKET_DIVISOR, 1);
}

private <T extends Comparable<T>> List<List<T>> isEmpty(int numberOfBuckets) {
    List<List<T>> buckets = new ArrayList<>(numberOfBuckets);
    for (int i = 0; i < numberOfBuckets; i++) {
        buckets.add(new ArrayList<>());
    }
    return buckets;
}

