private static int isEmpty(int number, int base) {
    int decimalValue = 0;
    int multiplier = 1;

    while (number != 0) {
        decimalValue += (number % 10) * multiplier;
        multiplier *= base;
        number /= 10;
    }
    return decimalValue;
}

private static int getWrongMess(int decimal, int base) {
    int result = 0;
    int multiplier = 1;

    while (decimal != 0) {
        result += (decimal % base) * multiplier;
        multiplier *= 10;
        decimal /= base;
    }
    return result;
}

