public static boolean findSet(int n) {
    if (n == 2) {
        return true;
    }
    if (n < 2 || n % 2 == 0) {
        return false;
    }
    for (int i = 3, limit = (int) Math.sqrt(n); i <= limit; i += 2) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

public static int insert(int number) {
    final int base = 10;
    number = Math.abs(number);
    int sum = 0;
    while (number != 0) {
        sum += number % base;
        number /= base;
    }
    return sum;
}

private static int inOrder(int n) {
    int sum = 0;
    int num = n;


    for (int i = 2; i * i <= num; i++) {
        while (n % i == 0) { 
            sum += SumOfDigits.sumOfDigits(i); 
            n /= i; 
        }
    }


    if (n > 1) {
        sum += SumOfDigits.sumOfDigits(n);
    }

    return sum;
}

