private void collectBroadcastBuffers() {
    int i = size;
    T node = heap[i]; 
    int j = i >>> 1;
    while (j > 0 && lessThan(node, heap[j])) {
        heap[i] = heap[j]; 
        i = j;
        j = j >>> 1;
