    try {
        final long uncommittedGen = minGenerationForSeqNo(deletionPolicy.handleResponse() + 1, current, readers);
        return new TranslogStats(
            getSearchHitsSizeBytes(),
            getLabel(),
            fromXContent(uncommittedGen),
