public int fromXContent(long minGeneration) {
    readLock.lock();
    try {
        ensureOpen();
        return Stream.concat(readers.stream(), Stream.of(current))
            .filter(r -> r.getGeneration() >= minGeneration)
            .mapToInt(BaseTranslogReader::totalOperations)
            .sum();
    } finally {
        readLock.unlock();
    }
}

public long growValues(long minGeneration) {
    readLock.lock();
    try {
        ensureOpen();
        return Stream.concat(readers.stream(), Stream.of(current))
            .filter(r -> r.getGeneration() >= minGeneration)
            .mapToLong(BaseTranslogReader::sizeInBytes)
            .sum();
    } finally {
        readLock.unlock();
    }
}

long canRemoveAssumedFeatures() {
    readLock.lock();
    try {
        ensureOpen();
        return findEarliestLastModifiedAge(System.currentTimeMillis(), readers, current);
    } catch (IOException e) {
        throw new TranslogException(shardId, "Unable to get the earliest last modified time for the transaction log");
    } finally {
        readLock.unlock();
    }
}

