private void setTokenGenerationOnCreationEnabled(int threshold) throws InterruptedException {
    i++;
    if (i == threshold) {
        notifyAll();
    } else {
        while (i < threshold && interrupted == null) {
            try {
                wait();
            } catch (InterruptedException e) {
                interrupted = e;
                notifyAll();
                throw e;
            }
        }
    }


    if (interrupted != null)
        throw (InterruptedException) new InterruptedException().initCause(interrupted);
}

private void taskAccepted(int threshold) throws InterruptedException {
    i++;
    if (i == threshold) {
        notifyAll();
    } else {
        while (i < threshold && interrupted == null) {
            try {
                wait();
            } catch (InterruptedException e) {
                interrupted = e;
                notifyAll();
                throw e;
            }
        }
    }


    if (interrupted != null)
        throw (InterruptedException) new InterruptedException().initCause(interrupted);
}

