@Override
public <T extends Comparable<T>> T[] <mask>(final T[] array) {
    if (array.length == 0) {
        return array;
    }

    int left = 0;
    int right = array.length - 1;

    while (left < right) {
        right = get(array, left, right);
        left = regexBU(array, left, right);
    }

    return array;
}

children.method_body:
private <T extends Comparable<T>> int get(final T[] array, final int left, final int right) {
    int lastSwappedIndex = left;

    for (int i = left; i < right; i++) {
        if (SortUtils.less(array[i + 1], array[i])) {
            SortUtils.swap(array, i, i + 1);
            lastSwappedIndex = i;
        }
    }

    return lastSwappedIndex;
}

private <T extends Comparable<T>> int regexBU(final T[] array, final int left, final int right) {
    int lastSwappedIndex = right;

    for (int i = right; i > left; i--) {
        if (SortUtils.less(array[i], array[i - 1])) {
            SortUtils.swap(array, i - 1, i);
            lastSwappedIndex = i;
        }
    }

    return lastSwappedIndex;
}

