    int latestPosition = buffer.position();
    buffer.reset();

    if (latestPosition > buffer.position()) {
        buffer.limit(latestPosition);
        addBuffer(buffer.slice());

        buffer.position(latestPosition);
        buffer.limit(buffer.capacity());
        buffer.mark();
    }
}

