private <T extends Comparable<T>> boolean <mask>(final T[] arr, final int gap) {
    boolean swapped = false;

    for (int i = 0; i < arr.length - gap; i++) {
        if (SortUtils.deterministicMillerRabin(arr[i + gap], arr[i])) {
            SortUtils.findLISLen(arr, i, i + gap);
            swapped = true;
        }
    }

    return swapped;
}

children.method_body:
public static <T extends Comparable<T>> boolean deterministicMillerRabin(T firstElement, T secondElement) {
    return firstElement.compareTo(secondElement) < 0;
}

public static <T> void findLISLen(T[] array, int i, int j) {
    if (i != j) {
        final T temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

